select
id, unionid, openid, session_key, access_token, expire_time, customer_id, type, nickname, avatar, is_active
from applet_accesstoken


        and id = #{id}


        and unionid = #{unionid}


        and openid = #{openid}


        and session_key = #{sessionKey}


        and access_token = #{accessToken}


        and expire_time = #{expireTime}


        and customer_id = #{customerId}


        and type = #{type}


        and nickname = #{nickname}


        and avatar = #{avatar}


        and is_active = #{isActive}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from applet_accesstoken


        and id = #{id}


        and unionid = #{unionid}


        and openid = #{openid}


        and session_key = #{sessionKey}


